 sideReady(q){if(q.cost)return this.afford(q.cost);if(q.building)return this.s.buildings.some(b=>b.type===q.building&&b.hp>0);return q.metric==='hospital'?this.qty('seedHerb')>0:!!this.s.stats[q.metric];}
